// Run first: the caller collects the returned `id` values (the 10 nearest docs overall) into a list.
query nearest_doc_ids($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id }
    order { nearest($d.embedding, $q) }
    limit 10
}
```

```gq
// Run second: the caller passes the ids from the first query as $ids, and reads the titles returned.
query titles_in_collection($ids: [String], $coll: String) {
    match {
        $d: Doc
        $d.id in $ids
        $c: Collection { slug: $coll }
        $d in $c
    }
    return { $d.title }
}
